div.script:
(() => {
  const grid = document.querySelector('.game-grid');
  const input = document.getElementById('search-input');
  const empty = document.querySelector('.no-results');
  const svg = document.documentElement;
  const foreignObject = svg.querySelector('foreignObject');
  const page = document.querySelector('.svg-page');
  if (!grid || !input || !empty || !foreignObject || !page) return;

  const fitViewport = () => {
    const width = Math.max(1, Math.round(window.innerWidth));
    const height = Math.max(1, Math.round(window.innerHeight));
    svg.setAttribute('viewBox', '0 0 ' + width + ' ' + height);
    foreignObject.setAttribute('width', width);
    foreignObject.setAttribute('height', height);
    page.style.height = height + 'px';
  };
  fitViewport();
  window.addEventListener('resize', fitViewport);

  const cards = Array.from(grid.querySelectorAll('.game-card'));
  cards.sort((a, b) => a.dataset.title.localeCompare(b.dataset.title));
  cards.forEach((card) => grid.appendChild(card));
  input.addEventListener('input', () => {
    const term = input.value.trim().toLocaleLowerCase();
    let visible = 0;
    cards.forEach((card) => {
      const matches = card.dataset.title.toLocaleLowerCase().includes(term);
      card.hidden = !matches;
      if (matches) visible += 1;
    });
    empty.hidden = term === '' || visible !== 0;
  });
})();
